    "[kengayish] #–# boshqa sensor (WSF#, # m) — «sakrash» ulushi oshgan, #–# bilan to'liq solishtirib bo'lmaydi": ['[expansion] #–# is a different sensor (WSF#, # m) — the share of leapfrog growth is inflated and not fully comparable with #–#', '[рост] #–# — другой сенсор (WSF#, # м): доля «скачкообразного» роста завышена, с #–# полностью не сопоставимо'],
